import{_ as e,a as o}from"./chunks/help-tips.DsVAi8vI.js";import{_ as s,o as n,c as a,a2 as r}from"./chunks/framework.Bzj1XTnB.js";const y=JSON.parse('{"title":"Tips, shortcuts and questions","description":"Lessons inside the app, handy shortcuts, keyboard keys and answers to common questions.","frontmatter":{"lang":"en","slug":"tips-and-help","order":11,"title":"Tips, shortcuts and questions","description":"Lessons inside the app, handy shortcuts, keyboard keys and answers to common questions."},"headers":[],"relativePath":"tips-and-help.md","filePath":"tips-and-help.md"}'),i={name:"tips-and-help.md"};function d(p,t,h,l,c,g){return n(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="tips-shortcuts-and-questions" tabindex="-1">Tips, shortcuts and questions <a class="header-anchor" href="#tips-shortcuts-and-questions" aria-label="Permalink to &quot;Tips, shortcuts and questions&quot;">​</a></h1><h2 id="lessons-inside-the-app" tabindex="-1">Lessons inside the app <a class="header-anchor" href="#lessons-inside-the-app" aria-label="Permalink to &quot;Lessons inside the app&quot;">​</a></h2><p><strong>Learn</strong> (bottom bar on the home screen) has short lessons: frame-by-frame basics, frames per second, onion skin, layers, lasso and copy-paste, ruler and mirror, audio, making a movie and the object library. Tap a lesson to open its steps.</p><p><img src="'+e+'" alt="How to animate"></p><p>In the editor, <strong>⋮ → Help &amp; tips</strong> explains every tool in a sentence or two.</p><p><img src="'+o+'" alt="Help and tips"></p><h2 id="handy-shortcuts" tabindex="-1">Handy shortcuts <a class="header-anchor" href="#handy-shortcuts" aria-label="Permalink to &quot;Handy shortcuts&quot;">​</a></h2><ul><li><strong>Double-tap Brush</strong> — ruler on or off.</li><li><strong>Double-tap Lasso</strong> — select everything on the layer.</li><li><strong>Two-finger tap</strong> — undo. <strong>Three-finger tap</strong> — redo.</li><li><strong>Long-press a frame</strong> — hold, duplicate, copy, paste, move, share.</li><li><strong>Long-press any button</strong> — shows its name.</li><li><strong>Copy, then Paste on another frame</strong> — the drawing lands in the same spot.</li></ul><h2 id="keyboard-tablets-and-phones-with-a-keyboard" tabindex="-1">Keyboard (tablets and phones with a keyboard) <a class="header-anchor" href="#keyboard-tablets-and-phones-with-a-keyboard" aria-label="Permalink to &quot;Keyboard (tablets and phones with a keyboard)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td>← / →</td><td>Previous / next frame</td></tr><tr><td>↑ / ↓</td><td>Layer above / below</td></tr><tr><td>Space</td><td>Play / stop</td></tr><tr><td>O</td><td>Onion skin on / off</td></tr><tr><td>B</td><td>Brush</td></tr><tr><td>E</td><td>Eraser</td></tr><tr><td>Ctrl + Z</td><td>Undo</td></tr><tr><td>Ctrl + Shift + Z or Ctrl + Y</td><td>Redo</td></tr></tbody></table><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><p><strong>Can I change the canvas size later?</strong> No — choose it when you create the project. The speed, timing, name and background can change any time.</p><p><strong>Why can&#39;t I add another layer?</strong> A project can have up to 15 layers. Merge two layers (swipe a layer to the left and tap <strong>Merge</strong>) or delete one you no longer need.</p><p><strong>My sticker pack has no &quot;Add to WhatsApp&quot; button.</strong> It does, but it stays faded until the pack has 3 stickers — WhatsApp won&#39;t take fewer. Make more stickers into the same pack.</p><p><strong>Something I moved off the canvas disappeared.</strong> In a project without room around the canvas, whatever is outside the canvas is cut when you put it down. Turn on <strong>Project settings → Draw outside the canvas</strong> to have room around it (new projects have it already).</p><p><strong>Smooth zoom makes no difference on my phone.</strong> It needs Android 13 or newer, and it only shows when you zoom in close. Check that <strong>Settings → Smooth zoom</strong> is on.</p><p><strong>Where are my movies?</strong> In the <strong>Movies</strong> tab of the home screen. Use <strong>Save to gallery</strong> to put a copy in your phone&#39;s gallery.</p><p><strong>How do I move my projects to a new phone?</strong> Long-press a project → <strong>Export project</strong>, send the <code>.flippa</code> file to the new phone, and open it with <strong>⋮ → Import project</strong>.</p><p><strong>Can I open my FlipaClip projects?</strong> Yes. Export the project from FlipaClip as a <code>.fc</code> file, then in Toonik use <strong>⋮ → Import project</strong>. The drawings and layers come across.</p><p><strong>Do I need an account? Does anything I draw get uploaded?</strong> No account is needed, and your drawings stay on your phone. Everything in Toonik is free.</p>',20)])])}const b=s(i,[["render",d]]);export{y as __pageData,b as default};
